EXTRAS = {1: "", 2: EXTRA2, 3: EXTRA3, 4: EXTRA4}
TIMES = {1: "0:00-0:50", 2: "0:50-1:42", 3: "1:42-2:36", 4: "2:36-3:28"}

for n in (1, 2, 3, 4):
    a = (n - 1) * 12 + 1
    nums = ["%02d" % (a + i) for i in (0, 2, 3, 5, 6, 8, 9, 11)]
    style = STYLE.format(n=n, a=nums[0], b=nums[1], c=nums[2], d=nums[3], e=nums[4], f=nums[5], g=nums[6], h=nums[7])
    parts = [style, SPUD, ALIENS, SHIP, PAST, TODAY]
    if EXTRAS[n]: parts.append(EXTRAS[n])
    parts += [LIGHT.format(light=LIGHTS[n]), PANELS[n]]
    head = "# Ancient aliens EP02 Stonehenge sheet %d of 4 (%s), 12 panels, 16:9 cells\n# Reference: references\\spud-reference-sheet-2026-11-11.png\n\nPROMPT START\n" % (n, TIMES[n])
    open(os.path.join(D, "sheet-%d-prompt.txt" % n), "w").write(head + "\n\n".join(parts) + "\n")

designs = "# Ancient aliens EP02 Stonehenge: design text (Fable, 13 Nov 2026)\n\nNew for this episode; aliens, ring ship, cutter and Spud's headlamp are the pilot's (../01-pyramids/DESIGNS.md).\n\n"
for title, body in [("1. STONEHENGE 2500 BC", PAST), ("2. STONEHENGE TODAY", TODAY), ("3. LIGHT AND THE PLAIN", LIGHT.format(light="A afternoon gold, B golden, C deep orange, D red sunset then dusk")), ("4. WALES, THE MAP, THE SHEPHERD", EXTRA2), ("5. JOINTS AND GROOVES", EXTRA3), ("6. PARCHMENT AND STONE AGE WORKERS", EXTRA4), ("7. RING SHIP (pilot's, sized to the circle)", SHIP)]:
    designs += "## %s\n%s\n\n" % (title, body)
open(os.path.join(D, "..", "DESIGNS.md"), "w").write(designs)
